/// The Gardiner name of a sign, if the tables have one.
pub fn gardiner(ch: char) -> Option<&'static str> {
    let i = NAMES.binary_search_by_key(&(ch as u32), |e| e.0).ok()?;
    Some(NAMES[i].1)
}

#[cfg(test)]
mod tests {
    #[test]
    fn names_are_sorted_and_found() {
        assert!(super::NAMES.windows(2).all(|w| w[0].0 < w[1].0));
        assert_eq!(super::gardiner('\u{13000}'), Some("A1"));
        assert_eq!(super::gardiner('\u{13461}'), Some("A1d"));
        assert_eq!(super::gardiner('\u{13460}'), None);
        assert_eq!(super::gardiner('a'), None);
    }
}
